examples.template:
Menu {
    Section({{label}}) {
        Button({{items.0.label}}) {}
            .keyboardShortcut("{{items.0.shortcut|raw}}", modifiers: [])
        Button({{items.1.label}}) {}
        Toggle({{watching.label}}, isOn: $isWatching)
    }
    Divider()
    Button({{delete}}, role: .destructive) {}
} label: {
    Label({{trigger}}, systemImage: "ellipsis.circle")
}
.buttonStyle(.monarch())

